from __future__ import annotations

import base64
import sqlite3
from typing import Callable

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse

from .db import connect, get_client
from .security import JWTManager, verify_secret

TOKEN_TTL = 3600


class OAuthError(Exception):
    """RFC 6749 §5.2 token endpoint error."""

    def __init__(self, status: int, error: str, description: str | None = None):
        self.status = status
        self.error = error
        self.description = description


def parse_basic_header(request: Request) -> tuple[str, str]:
    """Parse an HTTP Basic header; password may itself contain ':'."""
    header = request.headers.get("authorization")
    if header is None:
        raise OAuthError(401, "invalid_client", "missing Authorization header")
    scheme, _, value = header.partition(" ")
    if scheme.lower() != "basic":
        raise OAuthError(401, "invalid_client", "expected Basic authentication")
    try:
        decoded = base64.b64decode(value.strip(), validate=True).decode("utf-8")
    except Exception:
        raise OAuthError(401, "invalid_client", "malformed Basic credentials")
    # Split on the FIRST colon only: the secret is everything after it and
    # may contain further colons.
    client_id, sep, client_secret = decoded.partition(":")
    if not sep or not client_id:
        raise OAuthError(401, "invalid_client", "malformed Basic credentials")
    return client_id, client_secret


def create_app(
    db_path: str,
    jwt_manager: JWTManager,
    clock: Callable[[], float] | None = None,
) -> FastAPI:
    app = FastAPI(title="local-oauth2")
    db = connect(db_path)
    app.state.db = db
    app.state.jwt = jwt_manager

    @app.exception_handler(OAuthError)
    async def oauth_error_handler(request: Request, exc: OAuthError):
        headers = {}
        if exc.error == "invalid_client" and request.headers.get("authorization"):
            headers["WWW-Authenticate"] = 'Basic realm="oauth"'
        body = {"error": exc.error}
        if exc.description:
            body["error_description"] = exc.description
        return JSONResponse(status_code=exc.status, content=body, headers=headers)

    @app.post("/oauth/token")
    async def token(request: Request):
        form = await request.form()
        grant_type = form.get("grant_type")

        if grant_type != "client_credentials":
            raise OAuthError(
                400,
                "unsupported_grant_type",
                "only grant_type=client_credentials is supported",
            )

        client_id, client_secret = parse_basic_header(request)
        row = get_client(db, client_id)
        if row is None or not verify_secret(client_secret, row["secret_hash"]):
            raise OAuthError(401, "invalid_client", "client authentication failed")

        access_token, expires_in = jwt_manager.issue(subject=client_id)
        return JSONResponse(
            content={
                "access_token": access_token,
                "token_type": "Bearer",
                "expires_in": expires_in,
            },
            headers={"Cache-Control": "no-store", "Pragma": "no-cache"},
        )

    @app.get("/api/data")
    async def data(request: Request):
        auth = request.headers.get("authorization", "")
        scheme, _, value = auth.partition(" ")
        if scheme.lower() != "bearer" or not value.strip():
            return JSONResponse(
                status_code=401,
                content={"error": "unauthorized"},
                headers={"WWW-Authenticate": 'Bearer realm="api"'},
            )
        try:
            payload = jwt_manager.verify(value.strip())
        except Exception:
            return JSONResponse(
                status_code=401,
                content={"error": "invalid_token"},
                headers={
                    "WWW-Authenticate": 'Bearer error="invalid_token"'
                },
            )
        return {
            "data": ["alpha", "beta", "gamma"],
            "client_id": payload["sub"],
        }

    return app
"})
